using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    // ── FormatPhoneNumber ──────────────────────────────────────────

    [TestMethod]
    public void FormatPhoneNumber_ReturnsCorrectFormat()
    {
        var result = _formatter.FormatPhoneNumber("1234567890");

        Assert.AreEqual("(123) 456-7890", result);
        StringAssert.StartsWith(result, "(123)");
        StringAssert.EndsWith(result, "7890");
        StringAssert.Contains(result, "456");
    }

    [TestMethod]
    public void FormatPhoneNumber_StartsWithAreaCodeInParens()
    {
        var result = _formatter.FormatPhoneNumber("8005551234");

        StringAssert.StartsWith(result, "(800)");
    }

    [TestMethod]
    public void FormatPhoneNumber_EndsWithLastFourDigits()
    {
        var result = _formatter.FormatPhoneNumber("8005551234");

        StringAssert.EndsWith(result, "1234");
    }

    [TestMethod]
    public void FormatPhoneNumber_ContainsDashSeparator()
    {
        var result = _formatter.FormatPhoneNumber("8005551234");

        StringAssert.Contains(result, "-");
    }

    [TestMethod]
    public void FormatPhoneNumber_NullThrows()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _formatter.FormatPhoneNumber(null!));
    }

    [TestMethod]
    [DataRow("123")]
    [DataRow("12345678901")]
    [DataRow("")]
    public void FormatPhoneNumber_WrongLengthThrows(string digits)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.FormatPhoneNumber(digits));
    }

    // ── BuildGreeting ──────────────────────────────────────────────

    [TestMethod]
    public void BuildGreeting_DefaultTitle_ReturnsExpected()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.AreEqual("Dear Mr. Smith,", result);
        StringAssert.StartsWith(result, "Dear");
        StringAssert.EndsWith(result, ",");
    }

    [TestMethod]
    public void BuildGreeting_CustomTitle_StartsWithDearAndTitle()
    {
        var result = _formatter.BuildGreeting("Doe", "Dr.");

        StringAssert.StartsWith(result, "Dear Dr.");
        StringAssert.EndsWith(result, "Doe,");
    }

    [TestMethod]
    public void BuildGreeting_ContainsName()
    {
        var result = _formatter.BuildGreeting("Johnson", "Ms.");

        StringAssert.Contains(result, "Johnson");
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void BuildGreeting_InvalidNameThrows(string? name)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.BuildGreeting(name!));
    }

    // ── GenerateSlug ───────────────────────────────────────────────

    [TestMethod]
    public void GenerateSlug_SimpleTitle_ReturnsLowercaseDashed()
    {
        var result = _formatter.GenerateSlug("Hello World");

        Assert.AreEqual("hello-world", result);
    }

    [TestMethod]
    public void GenerateSlug_StartsWithFirstWord()
    {
        var result = _formatter.GenerateSlug("My Great Post");

        StringAssert.StartsWith(result, "my");
    }

    [TestMethod]
    public void GenerateSlug_EndsWithLastWord()
    {
        var result = _formatter.GenerateSlug("My Great Post");

        StringAssert.EndsWith(result, "post");
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharsCollapsedToDash()
    {
        var result = _formatter.GenerateSlug("C# is awesome!!!");

        Assert.AreEqual("c-is-awesome", result);
        StringAssert.StartsWith(result, "c-");
        StringAssert.EndsWith(result, "awesome");
    }

    [TestMethod]
    public void GenerateSlug_LeadingTrailingSpacesTrimmed()
    {
        var result = _formatter.GenerateSlug("  padded title  ");

        Assert.AreEqual("padded-title", result);
    }

    [TestMethod]
    public void GenerateSlug_MatchesSlugPattern()
    {
        var result = _formatter.GenerateSlug("Unit Testing 101!");

        StringAssert.Matches(result, new System.Text.RegularExpressions.Regex(@"^[a-z0-9]+(-[a-z0-9]+)*$"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GenerateSlug_InvalidTitleThrows(string? title)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.GenerateSlug(title!));
    }

    // ── FormatCurrency ─────────────────────────────────────────────

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWith_Dollar()
    {
        var result = _formatter.FormatCurrency(9.99m);

        StringAssert.StartsWith(result, "$");
        StringAssert.EndsWith(result, "9.99");
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_StartsWith_Symbol()
    {
        var result = _formatter.FormatCurrency(42.10m, "€");

        StringAssert.StartsWith(result, "€");
    }

    [TestMethod]
    public void FormatCurrency_TwoDecimalPlaces()
    {
        var result = _formatter.FormatCurrency(5m);

        StringAssert.EndsWith(result, "5.00");
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount_ContainsMinus()
    {
        var result = _formatter.FormatCurrency(-12.50m);

        StringAssert.Contains(result, "-");
        StringAssert.EndsWith(result, "12.50");
    }

    [TestMethod]
    public void FormatCurrency_Zero_FormatsCorrectly()
    {
        var result = _formatter.FormatCurrency(0m);

        Assert.AreEqual("$0.00", result);
    }
}

